"""Read variable length encoded 128 bits unsigned integer

    .. doctest::

        >>> from ppci.utils.leb128 import unsigned_leb128_decode
        >>> signed_leb128_decode(iter(bytes([0xe5, 0x8e, 0x26])))
        624485
    """
def unsigned_leb128_decode(data: Any) -> int {
    result = 0;
    shift = 0;
    while True {
        byte = next(data);
        result |= (byte & 127) << shift;
        if ((byte & 128) == 0) {
            break;
        }
        shift += 7;
    }
    return result;
}

"""Remove characters that may be changed when reformatting the text with black"""
def black_invariant(text: Any, chars: Any = None) -> object {
    if (chars is None) {
        chars = [' ', '\t', '\n', ',', "'", '"', '(', ')', '\\'];
    }
    for char in chars {
        text = text.replace(char, '');
    }
    return text;
}

